class Throttle:
    def __init__(self, rate_limit, period=1.0):
        self._rate_limit = rate_limit
        self._period = period
        self._calls = []

    def can_proceed(self):
        now = time.time()
        self._calls = [t for t in self._calls if now - t < self._period]
